#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; PROJECT_DIR="$(cd "$SCRIPT_DIR/../../.." && pwd)"; MANIFEST=""; TIME_LIMIT="15:00:00"; LIMIT=""; SERVICE_SMOKE=0; RETRY_FAILED=0; RETRY_INCOMPLETE=0; NODELIST=""; EXCLUDE="ainode01"; DRY_RUN=0
while [ "$#" -gt 0 ]; do case "$1" in --manifest) MANIFEST="$2";shift 2;; --time) TIME_LIMIT="$2";shift 2;; --limit) LIMIT="$2";shift 2;; --service-smoke) SERVICE_SMOKE=1;shift;; --retry-failed) RETRY_FAILED=1;shift;; --retry-incomplete) RETRY_INCOMPLETE=1;shift;; --nodelist) NODELIST="$2";shift 2;; --exclude) EXCLUDE="$2";shift 2;; --dry-run) DRY_RUN=1;shift;; --help|-h) printf 'Usage: %s --manifest PATH [--time VALUE] [--limit N] [--service-smoke] [--retry-failed] [--retry-incomplete] [--nodelist LIST] [--exclude LIST] [--dry-run]\n' "$0";exit 0;; *) exit 2;; esac; done
[ -n "$MANIFEST" ] || exit 2; cd "$PROJECT_DIR"; REPORT="$(mktemp)"; trap 'rm -f "$REPORT"' EXIT; PYTHONDONTWRITEBYTECODE=1 uv run --no-sync python "$SCRIPT_DIR/plan_qwen38_pairs.py" --manifest "$MANIFEST" --output "$REPORT" >/dev/null; COUNT="$(python -c 'import json,sys;print(json.load(open(sys.argv[1]))["pair_count"])' "$REPORT")"; ROOT="$(dirname "$MANIFEST")"; LOG_DIR="$ROOT/shared_gpu/slurm"; mkdir -p "$LOG_DIR"
CMD=(sbatch "--chdir=$PROJECT_DIR" --account=ais_login --qos=quota_ais_aiq --partition=aiq --gres=gpu:b200:2 --cpus-per-task=32 --mem=400G "--time=$TIME_LIMIT" --job-name=hackagent_qwen38_bf16_pair --output="$LOG_DIR/qwen38_bf16_%A_%a.out" --error="$LOG_DIR/qwen38_bf16_%A_%a.err" "--array=0-$((COUNT-1))"); [ -n "$NODELIST" ] && CMD+=("--nodelist=$NODELIST"); [ -n "$EXCLUDE" ] && CMD+=("--exclude=$EXCLUDE"); CMD+=("$SCRIPT_DIR/submit_qwen38_bf16_array.slurm" "$MANIFEST"); [ -n "$LIMIT" ] && CMD+=(--limit "$LIMIT"); [ "$SERVICE_SMOKE" -eq 1 ] && CMD+=(--service-smoke); [ "$RETRY_FAILED" -eq 1 ] && CMD+=(--retry-failed); [ "$RETRY_INCOMPLETE" -eq 1 ] && CMD+=(--retry-incomplete); printf 'pair_count=%s\nResolved sbatch command:' "$COUNT"; printf ' %q' "${CMD[@]}"; printf '\n'; [ "$DRY_RUN" -eq 0 ] && "${CMD[@]}"
